//! Embedded melodic instrument bank (Phase G) — the multi-sample voices.
//!
//! Loads the one-shot WAVs generated by `gen_instrument_bank` (Karplus-Strong
//! plucked strings + FM-style e-piano) through [`multisample::InstrumentBank`]
//! with a full SFZ-style zone manifest: key ranges, velocity layers, and
//! e-piano sustain loops.
//!
//! The bank is embedded via `include_bytes!` (R7 — no external runtime deps)
//! and fully deterministic (R2): identical bytes in → identical samples out.
//!
//! Instruments:
//! - `guitar` — plucked string, 4 key zones × 2 velocity layers
//! - `bass`   — plucked string in the low register, 3 zones × 2 layers
//! - `epiano` — looped additive tone, 3 zones

// Loop-point and sample-count math uses bounded f32/usize casts; the ranges
// are fixed by the asset generator (48 kHz, seconds-scale samples).
#![expect(
    clippy::cast_precision_loss,
    clippy::cast_possible_truncation,
    clippy::cast_sign_loss,
    reason = "Loop-point math converts fixed 48 kHz sample counts; assets are seconds-scale so truncation is lossless"
)]

use crate::multisample::{InstrumentBank, MultiSampleInstrument, Sample, SampleZone};

/// Bank target rate (assets are generated at 48 kHz).
pub const BANK_RATE: u32 = 48_000;

/// Build the embedded instrument bank.
///
/// The asset loader is deterministic and infallible: the WAVs ship in the
/// crate and the zone manifest is static, so failures here are programming
/// errors, not runtime conditions.
#[must_use]
pub fn embedded_instrument_bank() -> InstrumentBank {
    let mut bank = InstrumentBank::new();

    // Guitar: A2/E3/B3/E4 roots, soft + hard velocity layers. Zones merge
    // into the one `guitar` instrument (register replaces — the entry API
    // appends).
    for (root, key_min, key_max, wav_soft, wav_hard) in [
        (45u8, 40, 48, GUITAR_A2_SOFT, GUITAR_A2_HARD),
        (52, 49, 55, GUITAR_E3_SOFT, GUITAR_E3_HARD),
        (59, 56, 62, GUITAR_B3_SOFT, GUITAR_B3_HARD),
        (66, 63, 72, GUITAR_E4_SOFT, GUITAR_E4_HARD),
    ] {
        push_zones(
            &mut bank,
            "guitar",
            vec![
                SampleZone {
                    key_min,
                    key_max,
                    vel_min: 0.0,
                    vel_max: 0.62,
                    samples: vec![load_zone(root, wav_soft)],
                },
                SampleZone {
                    key_min,
                    key_max,
                    vel_min: 0.62,
                    vel_max: 1.0,
                    samples: vec![load_zone(root, wav_hard)],
                },
            ],
        );
    }

    // Bass: A1/C2/G2 roots, soft + hard layers.
    for (root, key_min, key_max, wav_soft, wav_hard) in [
        (29u8, 24, 32, BASS_A1_SOFT, BASS_A1_HARD),
        (36, 33, 39, BASS_C2_SOFT, BASS_C2_HARD),
        (43, 40, 47, BASS_G2_SOFT, BASS_G2_HARD),
    ] {
        push_zones(
            &mut bank,
            "bass",
            vec![
                SampleZone {
                    key_min,
                    key_max,
                    vel_min: 0.0,
                    vel_max: 0.62,
                    samples: vec![load_zone(root, wav_soft)],
                },
                SampleZone {
                    key_min,
                    key_max,
                    vel_min: 0.62,
                    vel_max: 1.0,
                    samples: vec![load_zone(root, wav_hard)],
                },
            ],
        );
    }

    // E-piano: C3/C4/C5 roots, looped sustain.
    for (root, key_min, key_max, wav) in [
        (48u8, 36, 54, EPIANO_C3),
        (60, 55, 66, EPIANO_C4),
        (72, 67, 84, EPIANO_C5),
    ] {
        let mut sample = load_zone(root, wav);
        // Loop the sustain: start just after the attack transient (~40 ms),
        // end just before the release fade (last 400 ms dropped).
        let loop_start = (0.04 * BANK_RATE as f32) as usize;
        let loop_end = sample
            .data
            .len()
            .saturating_sub((0.4 * BANK_RATE as f32) as usize);
        sample.loop_start = Some(loop_start.min(loop_end.saturating_sub(1)));
        sample.loop_end = Some(loop_end.max(loop_start + 1));
        push_zones(
            &mut bank,
            "epiano",
            vec![SampleZone {
                key_min,
                key_max,
                vel_min: 0.0,
                vel_max: 1.0,
                samples: vec![sample],
            }],
        );
    }

    bank
}

/// Append zones to a (possibly already-present) instrument, creating it if
/// needed. `register` replaces whole instruments; multi-root instruments
/// need this merge.
fn push_zones(bank: &mut InstrumentBank, name: &str, zones: Vec<SampleZone>) {
    if let Some(instrument) = bank.get_mut(name) {
        instrument.zones.extend(zones);
    } else {
        bank.register(MultiSampleInstrument {
            name: name.to_string(),
            zones,
        });
    }
}

/// Decode an embedded WAV one-shot into a [`Sample`].
///
/// `include_bytes!` data is `'static`; hound parses it in-memory (no I/O).
/// The assets are 24-bit PCM mono at 48 kHz — exactly `BANK_RATE`, so no
/// rate conversion is needed. Malformed embedded assets are a build-time
/// error, surfaced as a panic with a clear message (defensive: the generator
/// is the only writer of these files).
fn load_zone(root_note: u8, wav: &'static [u8]) -> Sample {
    #[expect(
        clippy::expect_used,
        reason = "Embedded assets are built by the crate's own generator; a parse failure is a build-time error"
    )]
    let (data, rate) = crate::wav::read_wav_mono(wav).expect("embedded bank WAV must parse");
    let data = crate::wav::convert_rate(&data, rate, BANK_RATE);
    Sample {
        root_note,
        data,
        sample_rate: BANK_RATE,
        loop_start: None,
        loop_end: None,
    }
}

// ── Embedded assets (generated by `gen_instrument_bank`) ────────────────

const GUITAR_A2_SOFT: &[u8] = include_bytes!("../assets/instruments/guitar_45_soft.wav");
const GUITAR_A2_HARD: &[u8] = include_bytes!("../assets/instruments/guitar_45_hard.wav");
const GUITAR_E3_SOFT: &[u8] = include_bytes!("../assets/instruments/guitar_52_soft.wav");
const GUITAR_E3_HARD: &[u8] = include_bytes!("../assets/instruments/guitar_52_hard.wav");
const GUITAR_B3_SOFT: &[u8] = include_bytes!("../assets/instruments/guitar_59_soft.wav");
const GUITAR_B3_HARD: &[u8] = include_bytes!("../assets/instruments/guitar_59_hard.wav");
const GUITAR_E4_SOFT: &[u8] = include_bytes!("../assets/instruments/guitar_66_soft.wav");
const GUITAR_E4_HARD: &[u8] = include_bytes!("../assets/instruments/guitar_66_hard.wav");

const BASS_A1_SOFT: &[u8] = include_bytes!("../assets/instruments/bass_29_soft.wav");
const BASS_A1_HARD: &[u8] = include_bytes!("../assets/instruments/bass_29_hard.wav");
const BASS_C2_SOFT: &[u8] = include_bytes!("../assets/instruments/bass_36_soft.wav");
const BASS_C2_HARD: &[u8] = include_bytes!("../assets/instruments/bass_36_hard.wav");
const BASS_G2_SOFT: &[u8] = include_bytes!("../assets/instruments/bass_43_soft.wav");
const BASS_G2_HARD: &[u8] = include_bytes!("../assets/instruments/bass_43_hard.wav");

const EPIANO_C3: &[u8] = include_bytes!("../assets/instruments/epiano_48.wav");
const EPIANO_C4: &[u8] = include_bytes!("../assets/instruments/epiano_60.wav");
const EPIANO_C5: &[u8] = include_bytes!("../assets/instruments/epiano_72.wav");

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_bank_loads_all_instruments() {
        let bank = embedded_instrument_bank();
        let names = bank.names();
        assert!(
            names.contains(&"guitar".to_string()),
            "guitar registered (got {names:?})"
        );
        assert!(names.contains(&"bass".to_string()));
        assert!(names.contains(&"epiano".to_string()));
        // 4 guitar zones × 2 layers + 3 bass × 2 + 3 epiano.
        #[expect(clippy::expect_used, reason = "Test assertions")]
        let guitar = bank.get("guitar").expect("guitar");
        #[expect(clippy::expect_used, reason = "Test assertions")]
        let bass = bank.get("bass").expect("bass");
        #[expect(clippy::expect_used, reason = "Test assertions")]
        let epiano = bank.get("epiano").expect("epiano");
        assert_eq!(guitar.zones.len(), 8);
        assert_eq!(bass.zones.len(), 6);
        assert_eq!(epiano.zones.len(), 3);
        assert!(bank.total_frames() > 0, "bank carries sample frames");
    }

    #[test]
    fn embedded_bank_is_deterministic() {
        let a = embedded_instrument_bank();
        let b = embedded_instrument_bank();
        assert_eq!(a.names(), b.names());
        #[expect(clippy::expect_used, reason = "Test assertions")]
        let guitar = a.get("guitar").expect("guitar");
        #[expect(clippy::expect_used, reason = "Test assertions")]
        let guitar_b = b.get("guitar").expect("guitar");
        for (zone, zone_b) in guitar.zones.iter().zip(&guitar_b.zones) {
            for (sample, sample_b) in zone.samples.iter().zip(&zone_b.samples) {
                assert_eq!(
                    sample.data, sample_b.data,
                    "identical bytes → identical samples (R2)"
                );
            }
        }
    }

    #[test]
    fn embedded_guitar_plays_pluck_without_clipping() {
        let bank = embedded_instrument_bank();
        let n = BANK_RATE as usize / 2;
        let mut out = vec![0.0; n];
        bank.render_note("guitar", 57, 0.8, 7, &mut out);
        let peak = out.iter().map(|s| s.abs()).fold(0.0f32, f32::max);
        assert!(peak > 0.05, "guitar produces sound (peak {peak})");
        assert!(peak <= 1.0, "no clipping (peak {peak})");
    }

    #[test]
    fn embedded_epiano_loops_for_a_full_note() {
        let bank = embedded_instrument_bank();
        // Note outlives the 3 s sample (4.5 s) so the sustain loop must
        // engage after the source is exhausted; without looping the tail
        // would be silence (the sample decays to ~0 by 3 s).
        let n = (BANK_RATE as f32 * 4.5) as usize;
        let mut out = vec![0.0; n];
        bank.render_note("epiano", 60, 0.7, 3, &mut out);
        // Loop must sustain through the whole note: last samples non-zero.
        let tail = &out[out.len() - 100..];
        let tail_peak = tail.iter().map(|s| s.abs()).fold(0.0f32, f32::max);
        assert!(tail_peak > 0.01, "epiano sustains (tail peak {tail_peak})");
    }
}
